class Solution {
public:
    vector<vector<int>> colorBorder(vector<vector<int>>& grid, int row, int col, int color) {
        int m = grid.size(), n = grid[0].size();
        int start_color = grid[row][col];
        if (start_color == color) return grid;

        vector<pair<int, int>> borders;
        vector<vector<bool>> visited(m, vector<bool>(n, false));

        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        auto dfs = [&](auto& self, int r, int c) -> void {
            visited[r][c] = true;
            bool is_border = false;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dirs[d][0], nc = c + dirs[d][1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                    is_border = true;
                } else if (!visited[nr][nc]) {
                    if (grid[nr][nc] == start_color) {
                        self(self, nr, nc);
                    } else {
                        is_border = true;
                    }
                }
            }
            if (is_border) borders.push_back({r, c});
        };

        dfs(dfs, row, col);
        for (const auto& p : borders) {
            grid[p.first][p.second] = color;
        }
        return grid;
    }
};

class Solution {
    public int[][] colorBorder(int[][] grid, int row, int col, int color) {
        int m = grid.length, n = grid[0].length;
        int startColor = grid[row][col];
        if (startColor == color) return grid;

        List<int[]> borders = new ArrayList<>();
        boolean[][] visited = new boolean[m][n];

        dfs(grid, row, col, startColor, visited, borders, m, n);

        for (int[] p : borders) {
            grid[p[0]][p[1]] = color;
        }
        return grid;
    }

    private void dfs(int[][] grid, int r, int c, int startColor, boolean[][] visited, List<int[]> borders, int m, int n) {
        visited[r][c] = true;
        boolean isBorder = false;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                isBorder = true;
            } else if (!visited[nr][nc]) {
                if (grid[nr][nc] == startColor) {
                    dfs(grid, nr, nc, startColor, visited, borders, m, n);
                } else {
                    isBorder = true;
                }
            }
        }
        if (isBorder) borders.add(new int[]{r, c});
    }
}

var colorBorder = function(grid, row, col, color) {
    const m = grid.length;
    const n = grid[0].length;
    const startColor = grid[row][col];
    if (startColor === color) return grid;

    const borders = [];
    const visited = new Array(m).fill(null).map(() => new Array(n).fill(false));

    const dfs = (r, c) => {
        visited[r][c] = true;
        let isBorder = false;
        const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                isBorder = true;
            } else if (!visited[nr][nc]) {
                if (grid[nr][nc] === startColor) {
                    dfs(nr, nc);
                } else {
                    isBorder = true;
                }
            }
        }
        if (isBorder) borders.push([r, c]);
    };

    dfs(row, col);
    for (const [r, c] of borders) {
        grid[r][c] = color;
    }
    return grid;
};
